def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    minimal = []

    def add_base(cls):
        if cls not in seen:
            seen.add(cls)
            for base in cls.__bases__:
                add_base(base)
            minimal.append(cls)

    for cls in classes:
        add_base(cls)

    # Reverse to get the correct MRO order
    minimal.reverse()

    # Remove any class that is a base of another in the list
    ordered_minimal = []
    for cls in minimal:
        if not any(issubclass(other, cls) for other in ordered_minimal):
            ordered_minimal.append(cls)

    return ordered_minimal
