def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.

    Args:
        indent (int): The level of indentation to use for formatting.
        debug (bool): If True, include debug information in the output.

    Returns:
        str: A pretty formatted string representation of self.
    """
    indent_str = ' ' * indent
    parts = [indent_str + "Instance of: {}".format(self.__class__.__name__)]
    for key, value in self.__dict__.items():
        if isinstance(value, (list, tuple, set, dict)):
            sub_indent = ' ' * (indent + 4)
            value_str = "\n".join([
                sub_indent + repr(item) if not isinstance(item, (str, int, float, type(None)))
                else sub_indent + repr(item)[:100] + ('...' if len(repr(item)) > 100 else '')
                for item in value
            ]) if isinstance(value, (list, tuple, set)) else \
            "\n".join([
                sub_indent + "{}: {}".format(k, repr(v)[:100] + ('...' if len(repr(v)) > 100 else ''))
                for k, v in value.items()
            ])
            parts.append(indent_str + "{}:\n{}".format(key, value_str))
        else:
            value_str = repr(value)
            if len(value_str) > 100:
                value_str = value_str[:100] + '...'
            parts.append(indent_str + "{}: {}".format(key, value_str))

