def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not version_dirs:
        raise ValueError("version_dirs must not be empty")

    root_inventory = self.load_inventory(version_dirs[0])  # Assuming a method to load inventory
    mismatched_digests = {}

    for version in version_dirs:
        current_inventory = self.load_inventory(version)
        if not current_inventory:
            raise ValueError(f"Missing inventory for version: {version}")

        for key, digest in current_inventory.items():
            if key in root_inventory and root_inventory[key] != digest:
                if version not in mismatched_digests:
                    mismatched_digests[version] = []
                mismatched_digests[version].append((key, root_inventory[key], digest))

    if mismatched_digests:
        raise ValueError("Mismatched content digests found across versions: {}".format(mismatched_digests))

