def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.strip()
    if not size:
        raise ValueError("Size string is empty")

    units = {'B': 1, 'K': 1000, 'M': 1000**2, 'G': 1000**3, 'T': 1000**4, 'P': 1000**5, 'E': 1000**6, 'Z': 1000**7, 'Y': 1000**8}
    if size[-1] in units:
        try:
            value = float(size[:-1])
        except ValueError:
            raise ValueError("Size string is not properly formatted")
        return int(value * units[size[-1]])
    else:
        try:
            return int(size)
        except ValueError:
            raise ValueError("Size string is not properly formatted")
